// sprzet, wykonanie[], polecenie, pomiar, normy[] (wiersze tabeli [grupa, wartość]), interpretacja, mcid, dlaczego,
// bledy[] – częste błędy pacjenta i badającego, muscles[] / joints[] – klucze z bazy, anim: { key – animacja z
